function reportAnalysis(expenses,person,start,end){
 const rows=expenses.filter(e=>e.beneficiary===person&&e.date>=start&&e.date<=end&&e.amount>0);
 const total=rows.reduce((s,e)=>s+e.amount,0),groups={};for(const e of rows)groups[e.category||'Otros']=(groups[e.category||'Otros']||0)+e.amount;
 const categories=Object.entries(groups).sort((a,b)=>b[1]-a[1]);
 const ants=rows.filter(e=>!e.bill_id&&e.source!=='payment'&&!['Salud','Educación','Vivienda','Servicios','Seguros'].includes(e.category)&&e.amount<=500000&&/\b(cafe|cafecito|chicle\w*|kiosco|golosina\w*|alfajor\w*|snack\w*|desayuno|merienda)\b/i.test(String(e.description||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')));
 const antTotal=ants.reduce((s,e)=>s+e.amount,0),fixed=rows.filter(e=>e.bill_id||e.source==='payment').reduce((s,e)=>s+e.amount,0);
 const recommendations=[];
 if(!rows.length)recommendations.push('Registrá tus gastos de este período para poder analizar en qué se fue el dinero.');
 else {if(ants.length)recommendations.push(`Hay ${ants.length} compras pequeñas por ${money(antTotal)}. Si elegís reducirlas un 25%, la diferencia sería ${money(Math.round(antTotal*.25))} en un período similar.`);const discretionary=rows.filter(e=>!e.bill_id&&e.source!=='payment'&&!['Salud','Educación','Vivienda','Servicios','Seguros'].includes(e.category));const categoryTotals={};for(const e of discretionary)categoryTotals[e.category]=(categoryTotals[e.category]||0)+e.amount;const main=Object.entries(categoryTotals).sort((a,b)=>b[1]-a[1])[0];if(main)recommendations.push(`${main[0]} concentra ${money(main[1])} en compras cotidianas. Podés fijar un límite para el próximo período y comparar cómo evoluciona.`);if(!ants.length)recommendations.push('No se detectaron gastos hormiga con el criterio de cafés, snacks y similares de hasta $5.000.');if(rows.some(e=>e.category==='Otros'))recommendations.push('Hay compras en Otros. Si les ponés una categoría más precisa, el próximo informe será más útil.');}
 return {rows,total,count:rows.length,categories,ants,antTotal,fixed,recommendations,largest:[...rows].sort((a,b)=>b.amount-a.amount).slice(0,5)};
}
let reportPerson='owner',reportPeriod='month';
function reportRange(){if(reportPeriod==='week'){const date=new Date(state.today+'T12:00:00Z'),day=date.getUTCDay();date.setUTCDate(date.getUTCDate()-((day+6)%7));return {start:date.toISOString().slice(0,10),end:state.today}}const month=$('#month').value,[y,m]=month.split('-').map(Number);return {start:month+'-01',end:month+'-'+String(new Date(Date.UTC(y,m,0)).getUTCDate()).padStart(2,'0')}}
function reportsView(){const range=reportRange(),report=reportAnalysis(state.expenses,reportPerson,range.start,range.end),people=[['owner','Titular'],['partner','Cotitular'],['shared','Compartidos']];const unassigned=state.expenses.filter(e=>(!e.beneficiary||e.beneficiary==='unassigned')&&e.date>=range.start&&e.date<=range.end).reduce((s,e)=>s+e.amount,0);return `<div class="toolbar"><label>Período<select id="report-period"><option value="month">Mes seleccionado</option><option value="week">Semana actual · lunes a hoy</option></select></label><span>${dateLabel(range.start)} al ${dateLabel(range.end)}</span></div><div class="metrics report-metrics">${people.map(([person,label])=>{const a=reportAnalysis(state.expenses,person,range.start,range.end);return `<button class="metric metric-link ${person===reportPerson?'emphasis':''}" data-report-person="${person}" aria-pressed="${person===reportPerson}"><span class="metric-top">${label}</span><strong>${money(a.total)}</strong><small>${a.count} movimientos · Ver informe</small></button>`}).join('')}</div><p class="notice">Los gastos personales corresponden a la persona asignada en cada movimiento. Los compartidos se muestran completos por separado, sin repartirlos automáticamente.${unassigned?' Hay '+money(unassigned)+' sin persona asignada, fuera de estos tres totales.':''}</p><div class="grid"><article class="card report-card"><div class="card-head"><h2>Informe de ${people.find(p=>p[0]===reportPerson)[1]}</h2></div><div class="report-content"><p><strong>${money(report.total)}</strong> en ${report.count} movimientos.</p><p>Pagos fijos registrados: ${money(report.fixed)}<br>Compras cotidianas: ${money(report.total-report.fixed)}</p><h3>En qué se gastó más</h3>${report.categories.length?report.categories.map(([cat,n])=>`<div class="bar-row"><div class="bar-label"><span>${esc(cat)}</span><strong>${money(n)} · ${Math.round(n/report.total*100)}%</strong></div><div class="bar"><div class="bar-fill" style="width:${n/report.total*100}%"></div></div></div>`).join(''):'<p>No hay movimientos en este período.</p>'}</div></article><article class="card report-card"><div class="card-head"><h2>Recomendaciones</h2></div><div class="report-content">${report.recommendations.map(t=>`<p>${esc(t)}</p>`).join('')}<h3>Posibles gastos hormiga</h3><p>${report.ants.length} compras · ${money(report.antTotal)}</p><small>Se consideran cafés, snacks y similares de hasta $5.000. Se excluyen salud, pagos fijos y servicios. Es una oportunidad para evaluar, no una obligación de eliminarlos.</small><p class="report-note">Este informe usa lo registrado. Sin ingresos y objetivos de ahorro no calcula cuánto pueden ahorrar realmente. Se actualiza sin consumir tokens de IA.</p></div></article></div><article class="card report-detail"><div class="card-head"><div><h2>Mayores gastos del período</h2><p>Hasta cinco movimientos del informe seleccionado.</p></div></div>${expenseTable(report.largest)}</article><article class="card report-detail"><div class="card-head"><div><h2>Todos los movimientos de ${people.find(p=>p[0]===reportPerson)[1]}</h2><p>${report.count} registros</p></div></div>${expenseTable(report.rows)}</article>`}
function occurrencesForMonth(events,month){return events.flatMap(e=>{if(e.recurrence!=='monthly')return e.date.startsWith(month)?[e]:[];if(month<e.date.slice(0,7))return [];const [y,m]=month.split('-').map(Number),day=Math.min(e.anchor||Number(e.date.slice(-2)),new Date(Date.UTC(y,m,0)).getUTCDate());const date=month+'-'+String(day).padStart(2,'0');return date<e.date?[]:[{...e,date}] }).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))}
'use strict';
let sessionCSRF=document.querySelector('meta[name="csrf-token"]')?.content||'';const originalFetch=window.fetch.bind(window);window.fetch=(url,options={})=>{const headers=new Headers(options.headers||{});if(new URL(url,location.href).origin===location.origin&&!['GET','HEAD'].includes((options.method||'GET').toUpperCase()))headers.set('X-CSRF-Token',sessionCSRF);return originalFetch(url,{...options,headers}).then(r=>{if(r.status===401&&new URL(url,location.href).pathname.startsWith('/api/'))location.replace('/ingresar');return r})};
