const $=s=>document.querySelector(s);let selectedCalendarDate=null;let forecastExpanded=false;let eventEditing=null,agendaPerson='all';let receiptTarget=null,receiptUploadId=null;let state,view='overview',editing=null,formKind='expense',search='',filter='all',rubroFilter='all',personFilter='all';
const money=v=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:v%100?2:0}).format(v/100);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('es-AR',{day:'numeric',month:'short'}):'Sin fecha';
const days=d=>d?Math.round((Date.parse(d+'T12:00:00Z')-Date.parse(state.today+'T12:00:00Z'))/86400000):null;
const names={overview:['Tu mes, en orden.','Una mirada clara a tus pagos y gastos del mes.','Resumen'],bills:['Tus pagos, a tiempo.','Organizá los vencimientos y anticipá cada compromiso.','Pagos y vencimientos'],expenses:['Cada gasto cuenta.','Registrá lo cotidiano y entendé a dónde va tu dinero.','Mis gastos'],agenda:['Tu agenda.','Eventos y compromisos en horario local.','Agenda'],calendar:['Un mes bien organizado.','Todos tus vencimientos en un solo lugar.','Calendario'],receipts:['Tus comprobantes.','Capturas de transferencias y archivos asociados a cada gasto o pago.','Comprobantes'],reports:['Tus informes.','Gastos de Titular, Cotitular y compartidos, con recomendaciones de gestión.','Informes'],settings:['A tu manera.','Configurá tu presupuesto y conectá tus recordatorios.','Configuración'],ai:['Laboratorio de IA & Visión Multimodal','Simulación en vivo del pipeline OpenAI GPT-4.1 Vision, JSON Schema y Bot Telegram.','Laboratorio IA']};
async function api(url,method='GET',data){const r=await fetch(url,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});if(!r.ok){let e;try{e=await r.json()}catch{e={error:'No se pudo conectar con el servidor'}}throw Error(e.error)}return r.json()}
let loadPromise=null;function load(){if(loadPromise)return loadPromise;loadPromise=(async()=>{try{try { state=await api('/api/state'); } catch(e) { state=getFinanzasDemoState(); }if(state.csrf)sessionCSRF=state.csrf;document.body.removeAttribute('data-session-loading');if(state.account&&!restoredView){view=names[state.account.view]?state.account.view:'overview';if(state.account.month)$('#month').value=state.account.month;restoredView=true;$('#manage-users').hidden=state.account.role!=='Administrador';}if(!$('#month').value)$('#month').value=state.today.slice(0,7);render()}finally{loadPromise=null}})();return loadPromise}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function badge(b){const d=days(b.due);return !b.active?'<span class="badge good">Completado</span>':d===null?'<span class="badge warn">Completar fecha</span>':d<0?'<span class="badge danger">Vencido</span>':d===0?'<span class="badge danger">Vence hoy</span>':d===1?'<span class="badge warn">Vence mañana</span>':`<span class="badge ${d<=7?'warn':''}">En ${d} días</span>`}
const icons={'Vivienda':'⌂','Servicios':'ϟ','Seguros':'◇','Educación':'▱','Transporte':'↔','Comida':'◉','Compras':'▧','Salud':'＋','Suscripciones':'⟳','Otros':'▤'};
function billsSorted(){return state.bills.filter(b=>b.active).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'))}
function lastPaymentLabel(b){const p=b.last_payment;return !p?'Sin pagos anteriores registrados':p.source==='payment'?`Último pago registrado: ${money(p.amount)} · ${dateLabel(p.date)}`:`Último importe en planilla: ${money(p.amount)} · ${p.period} (sin año)`}
function receiptsFor(type,id){const expenses=new Set(type==='bill'?state.expenses.filter(e=>e.bill_id===id).map(e=>e.id):[]);return (state.receipts||[]).filter(r=>r.target_type===type&&r.target_id===id||type==='bill'&&r.target_type==='expense'&&expenses.has(r.target_id))}
function receiptCount(type,id){return receiptsFor(type,id).length}
function receiptButton(type,id){const n=receiptCount(type,id);return `<button class="tiny" data-receipt-type="${type}" data-receipt-id="${esc(id)}">Subir comprobante${n?' ('+n+')':''}</button>`}
function receiptItem(r){return `<div class="receipt-item"><div><strong>${esc(r.filename)}</strong><small>${esc(r.target_label)} · ${r.target_type==='bill'?'Pago':'Gasto'} · ${new Date(r.created_at).toLocaleDateString('es-AR')} · ${(r.size/1024).toFixed(0)} KB</small></div><div class="row-actions"><button type="button" class="tiny" data-view-receipt="${esc(r.id)}">Ver comprobante</button><a class="tiny" href="/api/receipts/${encodeURIComponent(r.id)}" target="_blank" rel="noopener">Descargar</a><button type="button" class="tiny" data-delete-receipt="${esc(r.id)}">Eliminar</button></div></div>`}
function receiptsView(){const rows=state.receipts||[];return `<div class="toolbar"><button class="primary" id="new-receipt">＋ Agregar comprobante</button><span>${rows.length} archivos guardados</span></div><article class="card"><div class="card-head"><div><h2>Comprobantes de pago</h2><p>Al subir un comprobante a un pago pendiente, se registra el pago y avanza su vencimiento. Si elegís un gasto existente, solo se adjunta el archivo.</p></div></div>${rows.map(receiptItem).join('')||'<div class="empty">Todavía no hay comprobantes. Podés subir capturas, fotos o PDF.</div>'}</article>`}
function bindReceiptDeletes(root=document){root.querySelectorAll('[data-view-receipt]').forEach(b=>b.onclick=()=>openDocument(b.dataset.viewReceipt));root.querySelectorAll('[data-delete-receipt]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Eliminar este comprobante? El gasto o pago se conserva.'))return;b.disabled=true;try{await api('/api/receipts/'+b.dataset.deleteReceipt,'DELETE');await load();if($('#receipt-dialog').open)renderReceiptList();toast('Comprobante eliminado')}catch(e){toast(e.message);b.disabled=false}})}
function renderReceiptList(){const {type,id}=receiptTarget||{};$('#receipt-list').innerHTML=receiptsFor(type,id).map(receiptItem).join('')||'<p>No hay archivos asociados todavía.</p>';bindReceiptDeletes($('#receipt-list'))}
function receiptPaymentFields(){const {type,id}=receiptTarget||{};const bill=state.bills.find(b=>b.id===id);$('#receipt-payment-fields').innerHTML=type==='bill'&&bill?`<label class="field">Importe del comprobante<select id="receipt-mode"><option value="ai">Leer automáticamente con IA</option><option value="manual">Cargar importe manualmente</option></select></label><div class="field-pair"><label class="field" id="receipt-manual-field" hidden>Importe pagado (ARS)<input id="receipt-amount" type="number" min="0.01" max="1000000000" step="0.01" value="${bill.amount/100}"></label><label class="field">Fecha del pago<input id="receipt-date" type="date" required value="${state.today}"><small>La IA usará la fecha del recibo si se puede leer.</small></label></div><p>El importe leído se registra como pago y se usa como referencia para el próximo vencimiento. ${bill.due?`Se avanzará el vencimiento ${dateLabel(bill.due)}.`:'El próximo vencimiento queda por completar.'}</p>`:'<p>El gasto ya está registrado. El comprobante se adjunta sin duplicarlo.</p>';$('#receipt-submit').textContent=type==='bill'?'Leer comprobante y registrar pago':'Guardar comprobante';const mode=$('#receipt-mode');if(mode)mode.onchange=()=>{const manual=mode.value==='manual';$('#receipt-manual-field').hidden=!manual;$('#receipt-amount').required=manual;$('#receipt-submit').textContent=manual?'Guardar comprobante y registrar pago':'Leer comprobante y registrar pago'}}
function openReceipts(type,id){if(!type||!id){view='bills';render();toast('Tocá Subir comprobante en la fila del pago correspondiente.');return}const target=type==='bill'?state.bills.find(b=>b.id===id):state.expenses.find(e=>e.id===id);if(!target){toast('Actualizá la página para ver este pago.');return}receiptTarget={type,id};receiptUploadId=crypto.randomUUID();$('#receipt-form').reset();$('#receipt-associated').textContent='Comprobante para: '+(target.name||target.description);$('#receipt-error').textContent='';receiptPaymentFields();renderReceiptList();$('#receipt-dialog').showModal()}
function billRow(b,actions=false){return `<div class="bill-row"><span class="bill-icon">${icon(b.category==='Vivienda'?'house':b.category==='Seguros'?'shield':'bill')}</span><div><div class="name">${esc(b.name)}</div><small>${esc(b.rubro||'Por revisar')} · ${esc(personLabel(b.beneficiary))} · ${dateLabel(b.due)}</small><small>${esc(lastPaymentLabel(b))}</small></div><div class="right"><strong>${money(b.amount)}</strong>${badge(b)}</div>${actions?`<div class="row-actions">${b.active&&b.due?`<button class="tiny" data-pay="${b.id}">Marcar pagado</button>`:''}${receiptButton('bill',b.id)}<button class="tiny" data-edit="${b.id}">Editar</button></div>`:''}</div>`}
function expensesMonth(){return state.expenses.filter(e=>e.date.startsWith($('#month').value))}
function windowIcon(value){return icon({'↗':'arrow','▤':'bill','▦':'calendar','◇':'shield','✓':'check','◉':'bill'}[value]||'bill')}
function metric(label,value,note,icon,emphasis=false,target=''){const tag=target?'button':'div';return `<${tag} ${target?`type="button" data-summary="${target}" aria-label="${esc(label)}: ver detalle"`:''} class="metric ${emphasis?'emphasis':''}"><span class="metric-top">${label}<span class="metric-icon">${windowIcon(icon)}</span></span><strong>${value}</strong><small>${note}</small></${tag}>`}
function render(){if(state.account){clearTimeout(preferenceTimer);preferenceTimer=setTimeout(()=>api('/api/auth/preference','POST',{view,month:$('#month').value}).catch(()=>{}),700);}const n=names[view];$('#title').textContent=n[0];$('#subtitle').textContent=n[1];$('#crumb').textContent=n[2];document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#mobile-view').value=view;$('#view').innerHTML=({overview:overview,bills:billsView,expenses:expensesView,agenda:agendaView,calendar:calendarView,receipts:receiptsView,reports:reportsView,settings:settingsView,ai:aiView}[view])();bindView()}
function nextMonthCard(){const f=state.nextMonth;if(!f)return '';const monthLabel=new Date(f.month+'-01T12:00:00Z').toLocaleDateString('es-AR',{month:'long',year:'numeric',timeZone:'America/Argentina/Buenos_Aires'});return `<article class="card next-month"><div class="forecast-top"><div><h2>El mes que viene</h2><p>${esc(monthLabel)} · ${f.items.length} pagos previstos</p></div><div class="forecast-total"><strong>${money(f.total)}</strong><small>Total estimado</small></div></div><p class="forecast-note">Pagos mensuales y bimestrales que corresponden al próximo mes, con los montos de referencia actualizados. No incluye gastos diarios ni pagos únicos o anuales.</p>${f.missingAmount?`<p class="forecast-warning">Falta completar el importe de ${f.missingAmount} pago${f.missingAmount===1?'':'s'}. El total todavía está incompleto.</p>`:''}${f.missingDate?`<p class="forecast-note">${f.missingDate} pago${f.missingDate===1?' no tiene':'s no tienen'} fecha: ${f.missingDate===1?'su importe está incluido':'sus importes están incluidos'} en el total.</p>`:''}${f.items.length?`<details id="next-month-detail" ${forecastExpanded?'open':''}><summary>Ver detalle de los pagos</summary><p class="forecast-note">Las fechas se estiman según el día habitual de vencimiento. No suma pagos atrasados de otros meses.</p>${f.items.map(b=>`<div class="forecast-item"><div><strong>${esc(b.name)}</strong><small>${esc(personLabel(b.beneficiary))} · ${b.date?'Vence aprox. '+dateLabel(b.date):'Fecha por confirmar'}</small></div><strong>${b.amount>0?money(b.amount):'Importe por completar'}</strong></div>`).join('')}</details>`:'<div class="empty">Agregá tus pagos mensuales en Pagos y vencimientos para calcular el próximo mes.</div>'}</article>`}
function overview(){const exp=expensesMonth(),total=exp.reduce((s,e)=>s+e.amount,0),bs=billsSorted(),upcoming=bs.filter(b=>b.due&&days(b.due)>=0&&days(b.due)<=14),pending=bs.filter(b=>b.due?.startsWith($('#month').value)),unconfigured=bs.filter(b=>!b.due),overdue=bs.filter(b=>b.due&&days(b.due)<0);const grouped={};exp.forEach(e=>grouped[e.category]=(grouped[e.category]||0)+e.amount);const cats=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);return `<section class="hero compact"><div><div class="eyebrow">UN PASO ADELANTE</div><h2>${unconfigured.length?'Tu tranquilidad empieza con una fecha.':overdue.length?'Hay pagos que necesitan tu atención.':'Que ningún vencimiento te sorprenda.'}</h2><p>${unconfigured.length?`Tenés ${unconfigured.length} pagos por completar. Agregá sus vencimientos y dejá que los recordatorios se ocupen del resto.`:overdue.length?`Tenés ${overdue.length} pagos vencidos. Revisalos y marcá los que ya pagaste.`:`Tenés ${upcoming.length} pagos en los próximos 14 días. Todo a la vista, todo en orden.`}</p></div><button class="secondary" data-go="bills">${unconfigured.length?'Completar mis pagos':'Ver mis vencimientos'}</button></section>${nextMonthCard()}<section class="metrics">${metric('Gastos del mes',money(total),`${exp.length} movimientos registrados`,'↗',false,'expenses')}${metric('Pagos pendientes',money(pending.reduce((s,b)=>s+b.amount,0)),`${pending.length} vencimientos en el mes`,'▤',false,'month')}${metric('Próximos 14 días',money(upcoming.reduce((s,b)=>s+b.amount,0)),`${upcoming.length} pagos por delante`,'▦',false,'upcoming')}${metric('Por completar',unconfigured.length,'Pagos sin fecha de vencimiento','◇',true,'missing')}</section><section class="grid"><div><article class="card"><div class="card-head"><div><h2>Próximos vencimientos</h2><p>Anticipate a lo que viene.</p></div><button class="text-btn" data-go="bills">Ver todos</button></div>${bs.filter(b=>b.due).slice(0,4).map(b=>billRow(b,true)).join('')||'<div class="empty">Completá las fechas de tus pagos para verlos acá.</div>'}</article><div class="telegram-card"><span class="telegram-icon">${icon('send')}</span><div><h3>Tus finanzas, también en Telegram</h3><p>${state.telegram.configured?'Texto, gastos y recordatorios en tu chat.':'Un mensaje, un gasto registrado. Así de simple.'}</p></div><button class="text-btn" data-go="settings">${state.telegram.configured?'Ver conexión':'Conectar bot'}</button></div></div><article class="card"><div class="card-head"><div><h2>¿A dónde va tu dinero?</h2><p>Gastos por categoría este mes.</p></div><span class="badge">ARS</span></div><div class="distribution">${cats.length?cats.map(([cat,v],i)=>`<div class="bar-row"><div class="bar-label"><span>${esc(cat)}</span><strong>${money(v)}</strong></div><div class="bar"><div class="bar-fill" data-width="${Math.round(v/total*100)}" data-tone="${i%3}"></div></div><small>${Math.round(v/total*100)}% del total</small></div>`).join(''):'<div class="empty">Todavía no hay gastos este mes.<br>Registrá el primero para empezar a ver tu distribución.</div>'}</div></article></section><article class="card movements"><div class="card-head"><div><h2>Últimos movimientos</h2><p>Los pequeños gastos también cuentan.</p></div><button class="text-btn" data-go="expenses">Ver movimientos</button></div>${expenseTable(exp.slice(0,5))}</article>`}
function billsView(){let bs=state.bills.filter(b=>b.name.toLowerCase().includes(search.toLowerCase())&&(filter==='all'||filter==='missing'&&!b.due&&b.active||filter==='overdue'&&b.active&&b.due&&days(b.due)<0||filter==='active'&&b.active||filter==='month'&&b.active&&b.due?.startsWith($('#month').value)||filter==='upcoming'&&b.active&&b.due&&days(b.due)>=0&&days(b.due)<=14));bs=bs.filter(b=>(rubroFilter==='all'||b.rubro===rubroFilter)&&(personFilter==='all'||b.beneficiary===personFilter));bs.sort((a,b)=>(a.rubro||'Por revisar').localeCompare(b.rubro||'Por revisar')||(a.due||'9999').localeCompare(b.due||'9999'));return `<div class="toolbar"><select id="rubro-filter" aria-label="Rubro de pagos"><option value="all">Todos los rubros</option>${state.rubros.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="person-filter" aria-label="Persona de pagos"><option value="all">Todas las personas</option>${Object.entries(state.people).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select><input id="search" placeholder="Buscar un pago…" aria-label="Buscar pago" value="${esc(search)}"><select id="filter" aria-label="Filtrar pagos"><option value="all">Todos los pagos</option><option value="active">Activos</option><option value="month">Pendientes del mes</option><option value="upcoming">Próximos 14 días</option><option value="missing">Sin vencimiento</option><option value="overdue">Vencidos</option></select><button class="primary" id="new-bill">＋ Agregar pago</button></div><div class="notice">El importe del próximo pago es una referencia basada en el último pago registrado o en tu planilla. Al subir un nuevo comprobante se actualiza con el importe abonado. Los avisos llegan 7 y 1 día antes, desde las 9:00 de la mañana, cuando Telegram y la automatización estén activos.</div><article class="card"><div class="card-head"><div><h2>${filter==='month'?'Pagos pendientes del mes':filter==='upcoming'?'Próximos 14 días':filter==='missing'?'Pagos sin vencimiento':'Mis compromisos'}</h2><p>${bs.length} pagos · Total: ${money(bs.reduce((sum,b)=>sum+b.amount,0))}</p></div></div><div class="table-wrap"><table><thead><tr><th>CONCEPTO</th><th>IMPORTE</th><th>VENCIMIENTO</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody>${bs.map(b=>`<tr><td data-label="Concepto"><strong>${esc(b.name)}</strong><small>${esc(b.rubro||'Por revisar')} · ${esc(b.category)} · ${esc(personLabel(b.beneficiary))} · ${b.recurrence==='monthly'?'Mensual':b.recurrence==='bimonthly'?'Bimestral':b.recurrence==='yearly'?'Anual':'Único'}</small></td><td data-label="Importe">${money(b.amount)}<small>${esc(lastPaymentLabel(b))}</small></td><td data-label="Vencimiento">${dateLabel(b.due)}</td><td data-label="Estado">${badge(b)}</td><td data-label="Acciones"><div class="row-actions"><button class="tiny" data-edit="${b.id}">Editar</button>${b.due&&b.active?`<button class="tiny" data-pay="${b.id}">Marcar pagado</button>`:''}${receiptButton('bill',b.id)}<button class="tiny" data-delete-bill="${b.id}" aria-label="Eliminar ${esc(b.name)}">×</button></div></td></tr>`).join('')}</tbody></table>${bs.length?'':'<div class="empty">No hay pagos con este filtro.</div>'}</div></article>`}
function expenseTable(exp,del=false){return exp.length?`<div class="table-wrap"><table><thead><tr><th>DESCRIPCIÓN</th><th>RUBRO / CATEGORÍA</th><th>PERSONA</th><th>FECHA</th><th>IMPORTE</th>${del?'<th></th>':''}</tr></thead><tbody>${exp.map(e=>`<tr><td data-label="Descripción"><strong>${esc(e.description)}</strong><small>${e.source==='telegram'?'Registró: '+esc(e.entered_by==='Titular'?personLabel('owner'):e.entered_by||personLabel('owner'))+' · Telegram':e.source==='payment'?'Pago confirmado':'Registro manual'}</small></td><td data-label="Rubro / categoría">${esc(e.rubro||'Por revisar')}<small>${esc(e.category)}</small></td><td data-label="Persona">${esc(personLabel(e.beneficiary))}</td><td data-label="Fecha">${dateLabel(e.date)}</td><td data-label="Importe"><strong>${money(e.amount)}</strong></td>${del?`<td data-label="Acciones">${receiptButton('expense',e.id)}<button class="tiny" data-edit-expense="${e.id}">Editar</button>${e.source==='payment'?`<button class="tiny" data-undo="${e.id}">Deshacer pago</button>`:`<button class="tiny" data-delete-expense="${e.id}" aria-label="Eliminar gasto">×</button>`}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay movimientos este mes. Empezá con tu primer gasto.</div>'}
function personLabel(key){return state.people?.[key]||'Por asignar'}
function segmentFields(b){return `<div class="field-pair"><label class="field">Rubro<select name="rubro"><option value="">Clasificar automáticamente</option>${state.rubros.map(x=>`<option ${x===b?.rubro?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="field">¿Para quién es?<select name="beneficiary"><option value="">Asignar automáticamente</option>${Object.entries(state.people).map(([k,v])=>`<option value="${k}" ${k===b?.beneficiary?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div>`}
function expensesView(){const all=expensesMonth(),exp=all.filter(e=>(rubroFilter==='all'||e.rubro===rubroFilter)&&(personFilter==='all'||e.beneficiary===personFilter));const total=xs=>money(xs.reduce((n,e)=>n+e.amount,0));const groups=[['Gastos de la casa',all.filter(e=>e.rubro==='Gastos de la casa')],['Servicios',all.filter(e=>e.rubro==='Servicios')],['Personales · '+personLabel('owner'),all.filter(e=>e.rubro==='Personales'&&e.beneficiary==='owner')],['Personales · '+personLabel('partner'),all.filter(e=>e.rubro==='Personales'&&e.beneficiary==='partner')]];const review=all.filter(e=>!e.rubro||e.rubro==='Por revisar'||e.beneficiary==='unassigned');return `<section class="metrics">${groups.map(([label,rows])=>metric(esc(label),total(rows),rows.length+' movimientos','▤')).join('')}</section>${review.length?`<div class="notice">${review.length} movimientos por revisar o asignar. Tocá Editar para indicar el rubro y la persona.</div>`:''}<div class="toolbar"><label>Rubro<select id="rubro-filter"><option value="all">Todos los rubros</option>${state.rubros.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Persona<select id="person-filter"><option value="all">Todas las personas</option>${Object.entries(state.people).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><strong>Total seleccionado: ${total(exp)}</strong></div>${state.rubros.filter(r=>exp.some(e=>e.rubro===r)).map(r=>{const rows=exp.filter(e=>e.rubro===r);return `<article class="card movements"><div class="card-head"><div><h2>${esc(r)}</h2><p>${rows.length} movimientos · ${total(rows)}</p></div></div>${expenseTable(rows,true)}</article>`}).join('')||'<div class="empty">No hay gastos con estos filtros.</div>'}<button class="secondary" id="new-expense">Registrar gasto</button> <button class="secondary" id="csv">Exportar CSV del mes</button>`}
function eventTime(e){return e.time||'Hora por confirmar'}
function eventPerson(key){return key==='shared'?'Compartidos':personLabel(key)}
function agendaView(){const events=occurrencesForMonth(state.events||[],$('#month').value).filter(e=>(agendaPerson==='all'||e.person===agendaPerson));return `<div class="toolbar"><button class="primary" id="new-event">＋ Registrar evento</button><label>Agenda de<select id="agenda-person"><option value="all">Todos</option><option value="owner">Titular</option><option value="partner">Cotitular</option><option value="shared">Compartidos</option></select></label><span>${events.length} eventos este mes</span></div><div class="notice">También por texto o audio en Telegram: “Agendá el 14/10 a las 18:30 reunión con el contador”. Se guarda sin confirmación. Para un evento de ambos, agregá “para ambos”. Consultá <code>/agenda</code> en el bot.</div><article class="card"><div class="card-head"><div><h2>Eventos del mes</h2><p>Horario local · UTC−3</p></div></div>${events.map(e=>`<div class="agenda-item"><div class="agenda-when"><strong>${dateLabel(e.date)}</strong><span>${eventTime(e)}</span></div><div class="agenda-detail"><strong>${esc(e.title)}</strong><small>${esc(eventPerson(e.person))}${e.recurrence==='monthly'?' · Cada mes, día '+e.anchor:''}${e.source==='telegram'?' · Registró '+esc(e.entered_by||'')+' en Telegram':''}</small>${e.notes?`<p>${esc(e.notes)}</p>`:''}</div><div class="row-actions"><button class="tiny" data-edit-event="${esc(e.id)}">Editar</button><button class="tiny" data-delete-event="${esc(e.id)}">Eliminar</button></div></div>`).join('')||'<div class="empty">No hay eventos con este filtro. Registrá el primero desde acá o desde Telegram.</div>'}</article>`}
function openEvent(event=null){eventEditing=event?.id||null;$('#event-title').textContent=event?'Editar evento':'Registrar evento';$('#event-form').reset();for(const [name,value] of Object.entries({title:event?.title||'',date:event?.date||state.today,time:event?.time??'',person:event?.person||'shared',recurrence:event?.recurrence||'once',notes:event?.notes||''}))$('#event-form [name='+name+']').value=value;$('#event-error').textContent='';$('#event-dialog').showModal()}
function calendarView(){const month=$('#month').value,[y,m]=month.split('-').map(Number),n=new Date(y,m,0).getDate(),start=(new Date(y,m-1,1).getDay()+6)%7;if(!selectedCalendarDate?.startsWith(month))selectedCalendarDate=state.today.startsWith(month)?state.today:month+'-01';let html=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<div class="day-label">${d}</div>`).join('');html+='<div class="day blank" aria-hidden="true"></div>'.repeat(start);for(let d=1;d<=n;d++){const key=`${month}-${String(d).padStart(2,'0')}`,bs=state.bills.filter(b=>b.active&&b.due===key),activities=occurrencesForMonth(state.events||[],month).filter(e=>e.date===key),count=bs.length+activities.length;html+=`<div class="day ${key===state.today?'today':''} ${key===selectedCalendarDate?'selected':''}"><div class="day-desktop">${d}${bs.map(b=>`<button class="day-event" data-edit="${b.id}">${esc(b.name)}<br>${money(b.amount)}</button>`).join('')}${activities.map(e=>`<button class="day-event agenda-calendar-event" data-edit-event="${esc(e.id)}">${eventTime(e)} · ${esc(e.title)}<br>${esc(eventPerson(e.person))}</button>`).join('')}</div><button class="day-mobile" data-calendar-day="${key}" aria-label="${key}: ${count} eventos y pagos" aria-pressed="${key===selectedCalendarDate}"><span>${d}</span><span class="day-markers">${activities.length?'<i class="event-dot" aria-hidden="true"></i>':''}${bs.length?'<i class="payment-dot" aria-hidden="true"></i>':''}</span></button></div>`}const bs=state.bills.filter(b=>b.active&&b.due===selectedCalendarDate),events=occurrencesForMonth(state.events||[],month).filter(e=>e.date===selectedCalendarDate);return `<div class="calendar" aria-label="Calendario mensual">${html}</div><div class="calendar-mobile-details"><p class="calendar-note">Tocá un día para ver sus eventos y pagos. <span class="calendar-legend"><i class="event-dot"></i> Eventos <i class="payment-dot"></i> Pagos</span></p><article class="card"><div class="card-head"><h2>${esc(new Date(selectedCalendarDate+'T12:00:00').toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long'}))}</h2></div>${events.map(e=>`<button class="calendar-detail" data-edit-event="${esc(e.id)}"><strong>${eventTime(e)} · ${esc(e.title)}</strong><small>${esc(eventPerson(e.person))}</small></button>`).join('')}${bs.map(b=>`<button class="calendar-detail" data-edit="${esc(b.id)}"><strong>${esc(b.name)} · ${money(b.amount)}</strong><small>Pago · ${esc(personLabel(b.beneficiary))}</small></button>`).join('')}${events.length+bs.length?'':'<div class="empty">No hay eventos ni pagos para este día.</div>'}</article></div><p class="calendar-note calendar-desktop-note">Eventos y vencimientos en horario local. Tocá un evento o pago para editarlo.</p>`}
function settingsView(){if(state.account&&state.account.role!=='Administrador')return '<article class="card settings"><h2>Tu cuenta</h2><p>'+esc(state.account.name)+' · '+esc(state.account.email)+'</p><p>Podés registrar, editar y eliminar los gastos, pagos y eventos compartidos. El administrador gestiona usuarios y conexiones.</p><button class="secondary" id="backup">Descargar respaldo JSON</button></article>';const t=state.telegram;return `<article class="card settings"><h2>Telegram <span class="badge telegram-status ${t.configured?'good':'warn'}">${t.configured?'Vinculado':t.tokenSaved?'Esperando vinculación':'Sin conectar'}</span></h2><p>Registrá gastos desde tu chat y recibí avisos una semana y un día antes de cada vencimiento.</p><ol><li>Abrí <a href="https://t.me/BotFather" target="_blank" rel="noopener noreferrer">@BotFather</a>, enviá <code>/newbot</code> y elegí el nombre y usuario de tu bot.</li><li>Si ya tenés tu bot, usá su token existente en el campo de abajo. Se guarda cifrado y no vuelve a mostrarse.</li><li>Guardá la conexión. Tu chat privado ya está preparado; tocá <strong>Verificar conexión</strong> y luego <strong>Revisar Telegram</strong>.</li></ol>${!t.tokenSaved?`<form id="connect-bot"><label class="field">Token de BotFather<input name="token" type="password" required autocomplete="off" placeholder="Pegá el token de FinanzasProBot"></label><button class="primary" type="submit">Guardar conexión</button><p id="connection-error" role="alert"></p></form>`:`<div class="connection-box"><strong>@${esc(t.username)}</strong>${t.linkCode&&!t.configured?`<a class="primary" target="_blank" rel="noopener noreferrer" href="https://t.me/${encodeURIComponent(t.username)}?start=${encodeURIComponent(t.linkCode)}">Abrir y vincular mi bot</a>`:'<p>Tu chat privado está vinculado. Podés invitar a tu cotitular para compartir el registro.</p>'}<button class="secondary" id="verify-bot">Verificar conexión</button><button class="secondary" id="sync-bot">Revisar Telegram</button><button class="tiny" id="disconnect-bot">Desconectar</button></div>`}<p class="notice">Telegram recibe mensajes mediante su conexión en la nube. No necesita que dejes esta página abierta. Las consultas sin mensajes no consumen tokens de IA.</p>${t.lastSync?`<p>Última revisión: ${esc(new Date(t.lastSync).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}))}</p>`:''}${t.lastError?`<p class="error-box">${esc(t.lastError)}</p>`:''}<h3>Gestión compartida</h3><p>Compartí una invitación para que tu cotitular use el mismo bot desde su cuenta. El enlace vence en 24 horas y se usa una sola vez.</p><form id="invite-partner"><label class="field">Nombre del cotitular<input name="name" required maxlength="60" placeholder="Nombre que aparecerá en sus gastos"></label><button class="primary" type="submit">Crear invitación</button></form><div id="invite-result" role="status"></div>${(t.members||[]).map(m=>`<div class="connection-box"><strong>${esc(m.name)}</strong><button class="tiny" data-remove-member="${esc(m.chat_id)}">Quitar acceso al bot</button></div>`).join('')}<p>Ambos pueden consultar los totales compartidos. Los recordatorios siguen llegando al chat del titular. La invitación de Telegram vincula el bot. Para entrar a la página, creá también su invitación desde Usuarios.</p><h3>Gastos por mensaje</h3><p>Mandá <code>1500 de servicios</code>. El bot guarda el gasto directamente y te responde con lo registrado. Si no reconoce un importe único, te pide aclararlo. Consultá <code>/resumen</code> y <code>/vencimientos</code> cuando quieras.</p><h3>Notas de voz <span class="badge ${t.audio?'good':'warn'}">${t.audio?'Activas':'Por activar'}</span></h3><p>Podés dictar gastos cotidianos por voz. Para transcribir, conectá una clave de la API con saldo disponible. Cada audio se envía para transcripción; los gastos reconocidos se guardan directamente. Límite: 10 MB.</p><form id="connect-audio"><label class="field">Clave privada de API<input name="audioKey" type="password" autocomplete="off" required placeholder="Clave de tu cuenta de la API"></label><button class="secondary" type="submit">Guardar y activar audios</button><p id="audio-error" role="alert"></p></form>${t.audio?'<button class="tiny" id="pause-audio">Pausar audios</button>':''}<h3>Rubros y asignaciones</h3><p>Los gastos se organizan en Hogar, Servicios y Personales. Telegram identifica automáticamente al titular o cotitular por la cuenta que envía el mensaje. Una compra para la casa conserva quién la registró y queda como compartida. Los pagos fijos sin titular identificable quedan por asignar. En Mis gastos, tocá Editar para corregir descripción, importe, rubro o persona.</p><h3>Cómo usar tu página</h3><ol><li>En <strong>Pagos y vencimientos</strong>, revisá cada importe, cargá la próxima fecha y elegí si se repite cada mes, cada dos meses o cada año.</li><li>Cuando pagues, tocá <strong>Marcar pagado</strong>. Se registra el gasto y, si se repite, avanza un ciclo.</li><li>Usá <strong>Registrar gasto</strong> para compras cotidianas. Telegram guarda los gastos en el mismo registro.</li><li>El calendario muestra las fechas cargadas. Los recordatorios se envían desde las 9:00, horario local.</li></ol><h3>Tu planilla de control</h3><p>Se cargaron conceptos de referencia usando los últimos importes disponibles. Revisalos antes de pagar. Las fechas y vencimientos se actualizan automáticamente. Revisá si “Seguros Generales” y “Seguro Automotor” corresponden a obligaciones diferentes.</p><h3>Datos y respaldo</h3><p>Los datos requieren autenticación segura. La sesión se recuerda durante 30 días en este dispositivo. Pagos y gastos se guardan en la nube y aparecen desde tus distintos dispositivos. El respaldo excluye tokens y claves.</p><button class="secondary" id="backup">Descargar respaldo JSON</button></article>`}
function openForm(kind,b=null){formKind=kind;editing=b?.id||null;$('#form-error').textContent='';$('#form-title').textContent=kind==='bill'?(b?'Editar pago':'Nuevo pago'):kind==='budget'?'Presupuesto mensual':b?'Editar gasto':'Registrar gasto';const cats=state.categories.map(c=>`<option ${c===(b?.category||'Otros')?'selected':''}>${esc(c)}</option>`).join('');$('#fields').innerHTML=kind==='budget'?`<label class="field">Presupuesto mensual (ARS)<input name="amount" type="number" min="0" max="1000000000" step="0.01" required value="${state.budget/100}"></label>`:kind==='bill'?`<label class="field">Concepto<input name="name" required maxlength="120" placeholder="Ej. Seguro del auto" value="${esc(b?.name||'')}"></label><div class="field-pair"><label class="field">Importe (ARS)<input name="amount" type="number" min="0" max="1000000000" step="0.01" required value="${b?b.amount/100:''}" placeholder="0"></label><label class="field">Categoría<select name="category">${cats}</select></label></div><label class="field">Próximo vencimiento<input name="due" type="date" value="${b?.due||''}"><small>Sin fecha, este pago no generará avisos.</small></label><label class="field">Se repite<select name="recurrence"><option value="monthly">Cada mes</option><option value="bimonthly">Cada dos meses (bimestral)</option><option value="yearly">Cada año</option><option value="once">Pago único</option></select></label>`:`<label class="field">¿En qué gastaste?<input name="description" required maxlength="240" placeholder="Ej. Chicle en el kiosco"></label><div class="field-pair"><label class="field">Importe (ARS)<input name="amount" type="number" min="0.01" max="1000000000" step="0.01" required placeholder="1500"></label><label class="field">Categoría<select name="category">${cats}</select></label></div><label class="field">Fecha<input name="date" type="date" required value="${state.today}"></label>`;if(kind!=='budget')$('#fields').insertAdjacentHTML('beforeend',segmentFields(b));if(kind==='expense'&&b){$('#form [name=description]').value=b.description;$('#form [name=amount]').value=b.amount/100;$('#form [name=date]').value=b.date;}if(kind==='bill')$('#form [name=recurrence]').value=b?.recurrence||'monthly';if(kind==='expense'&&b){$('#fields').insertAdjacentHTML('beforeend',`<div class="field"><strong>Comprobantes de pago</strong><p>${receiptCount('expense',b.id)} archivos asociados</p><button type="button" class="secondary" id="edit-receipts">Agregar o ver comprobantes</button><small>Los archivos se guardan asociados a este gasto.</small></div>`);$('#edit-receipts').onclick=()=>openReceipts('expense',b.id)}const beneficiary=$('#form [name=beneficiary]');if(beneficiary){const applyShared=()=>{if(beneficiary.value==='shared'){$('#form [name=category]').value='Vivienda';$('#form [name=rubro]').value='Gastos de la casa'}};beneficiary.onchange=applyShared;applyShared();for(const name of ['category','rubro'])$('#form [name='+name+']').onchange=applyShared;}$('#dialog').showModal()}
