$('.logo').innerHTML='<img src="./fauvor/symbol.png" alt="" width="36" height="52">';document.querySelectorAll('.nav span').forEach((el,i)=>el.innerHTML=icon(['grid','bill','arrow','calendar','calendar','bill','settings','spark','settings'][i]||'spark'));$('.small-mark').innerHTML='<img src="./fauvor/symbol.png" alt="" width="30" height="44">';
let syncBusy=false,lastSyncError='';
async function syncTelegram(){if(syncBusy||!state||document.hidden)return;syncBusy=true;const modalOpen=()=>['#dialog','#receipt-dialog','#event-dialog','#document-dialog'].some(id=>$(id)?.open);try{const results=await Promise.allSettled([modalOpen()?Promise.resolve(null):load(),state.telegram.tokenSaved?api('/api/tick','POST',{}):Promise.resolve(null)]);const result=results[1];const error=result.status==='rejected'?result.reason.message:result.value?.status==='error'?result.value.error:'';if(error&&error!==lastSyncError)toast('Telegram: '+error);lastSyncError=error||'';if(result.status==='fulfilled'&&result.value?.processed>0&&!modalOpen())await load()}finally{syncBusy=false}}
load().then(syncTelegram).catch(e=>{$('#mobile-view').value=view;$('#view').innerHTML=`<div class="error-box">${esc(e.message)}. Recargá la página para reintentar.</div>`});setInterval(syncTelegram,10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncTelegram()});window.addEventListener('focus',syncTelegram);


if(document.modelContext?.registerTool){
const lifecycle=new AbortController();
for(const tool of [{name:'read_finances',description:'Consulta pagos y gastos guardados.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>{await load();return {bills:state.bills,expenses:state.expenses}}},{name:'register_expense',description:'Guarda un gasto con importe en pesos argentinos y actualiza el registro visible.',inputSchema:{type:'object',properties:{description:{type:'string'},amount:{type:'number',exclusiveMinimum:0},category:{type:'string'},date:{type:'string'}},required:['description','amount'],additionalProperties:false},execute:async input=>{await api('/api/expenses','POST',input);await load();return {saved:true}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

let documentController=null,documentUrl=null;
function clearDocument(){documentController?.abort();documentController=null;if(documentUrl)URL.revokeObjectURL(documentUrl);documentUrl=null;$('#document-preview').replaceChildren()}
async function openDocument(id){clearDocument();const receipt=state.receipts.find(r=>r.id===id);if(!receipt)return;const controller=new AbortController();documentController=controller;$('#document-title').textContent=receipt.filename;$('#document-status').textContent='Cargando comprobante…';$('#document-dialog').showModal();try{const response=await fetch('/api/receipts/'+encodeURIComponent(id)+'?view=1',{signal:controller.signal});if(!response.ok)throw Error('No pude abrir el comprobante. Reintentá.');const blob=await response.blob();if(controller.signal.aborted)return;if(receipt.content_type==='application/pdf'){const viewer=await import('/receipt-viewer.js');if(controller.signal.aborted)return;await viewer.openPdf(new Uint8Array(await blob.arrayBuffer()),$('#document-preview'),controller.signal)}else{documentUrl=URL.createObjectURL(blob);const image=document.createElement('img');image.alt='Comprobante: '+receipt.target_label;image.src=documentUrl;$('#document-preview').append(image);await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('No se pudo mostrar la imagen.'))})}if(!controller.signal.aborted)$('#document-status').textContent=''}catch(e){if(!controller.signal.aborted)$('#document-status').textContent=e.message}}
$('#close-document').onclick=()=>$('#document-dialog').close();$('#document-dialog').addEventListener('close',clearDocument);
$('#close-receipt').onclick=()=>$('#receipt-dialog').close();
$('#receipt-form').onsubmit=async e=>{e.preventDefault();const button=$('#receipt-submit');button.disabled=true;$('#receipt-error').textContent='';try{const file=$('#receipt-file').files[0];if(!file||file.size>10*1024*1024)throw Error('Elegí un comprobante de hasta 10 MB');const {type:targetType,id:targetId}=receiptTarget||{};if(!targetId)throw Error('Elegí un gasto o pago');const data=new FormData();data.append('targetType',targetType);data.append('targetId',targetId);data.append('file',file);data.append('uploadId',receiptUploadId);if(targetType==='bill'){data.append('due',state.bills.find(b=>b.id===targetId).due||'');data.append('readMode',$('#receipt-mode').value);if($('#receipt-mode').value==='manual')data.append('amount',$('#receipt-amount').value);button.textContent=$('#receipt-mode').value==='ai'?'Leyendo comprobante…':'Guardando…';data.append('date',$('#receipt-date').value)}const r=await fetch('/api/receipts',{method:'POST',body:data});if(!r.ok){const error=await r.json();throw Error(error.error||'No se pudo guardar el comprobante')}const saved=await r.json();$('#receipt-file').value='';$('#receipt-dialog').close();toast(saved.paid?`Guardado con éxito: ${saved.amount!=null?money(saved.amount)+' · ':''}pago registrado y referencia actualizada`:'Comprobante guardado con éxito');await load().catch(()=>toast('Guardado con éxito. Recargá la página para actualizar la vista.'))}catch(err){$('#receipt-error').textContent=err.message}finally{button.disabled=false;if($('#receipt-dialog').open)button.textContent=receiptTarget?.type==='bill'&&$('#receipt-mode')?.value==='ai'?'Leer comprobante y registrar pago':'Guardar comprobante'}};



$('#close-event').onclick=$('#cancel-event').onclick=()=>$('#event-dialog').close();
$('#event-form').onsubmit=async e=>{e.preventDefault();const button=$('#event-submit');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await api('/api/events'+(eventEditing?'/'+eventEditing:''),eventEditing?'PUT':'POST',data);$('#month').value=data.date.slice(0,7);view='agenda';$('#event-dialog').close();await load();toast('Evento guardado')}catch(err){$('#event-error').textContent=err.message}finally{button.disabled=false}};

$('#logout').onclick=async()=>{try{await api('/api/auth/logout','POST',{});location.replace('/ingresar')}catch(e){toast(e.message)}};
